                    hopCount++
                    if (hopCount == 1) {
                        respond(
                            content = "",
                            status = HttpStatusCode.Found,
                            headers = headersOf("Location", "?page=2"),
                        )
                    } else {
                        secondHopUrl = req.url.toString()
