                    runBlocking {
                        client.sendRequest("GET", "$chasmUrl$path", emptyMap(), null)
                    }
                assertEquals(302, response.statusCode, path)
                assertEquals("{\"redirect\":\"$marker\"}", response.body.filterNot { it.isWhitespace() }, path)
            }
        }
    }

