    @Nested
    @DisplayName("HTTPS->HTTP redirect body-replay guard (N1)")
    inner class HttpsToHttpRedirectBodyReplay {
        /*
         * N1: the HTTPS->HTTP body-replay guard fires ONLY for 307/308 (the
         * status codes that preserve method+body). For 301/302/303 the request
         * is downgraded to GET and the body is dropped per RFC, so there is no
         * TLS-protected payload to leak and the redirect must proceed. A
         * MockEngine stages the cross-scheme hop deterministically (chasm can't
         * easily downgrade HTTPS->HTTP); only the guard logic is under test.
         */
        @Test
        @DisplayName(
            "bhvRedirects001 N1: 302 HTTPS->HTTP with a body is refused (the body is never replayed in plain text and the call fails)",
        )
        fun redirect302HttpsToHttpWithBodyIsRefused() {
            var hopCount = 0
            val engine =
                MockEngine { _ ->
                    hopCount++
                    respond(
                        content = "",
                        status = HttpStatusCode.Found,
                        headers = headersOf("Location", "http://insecure.example.com/dest"),
                    )
                }
            val transport = TransportOptions.builder().followRedirects(true).build()
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false }, transport)
            assertThrows(com.example.petstore.errors.OpenAPIException::class.java) {
                runBlocking {
                    apiClient.sendRequest("POST", "https://secure.example.com/x", emptyMap(), "secret-body")
                }
            }
            assertEquals(1, hopCount, "the refused redirect must not be followed")
        }

        @Test
        @DisplayName("bhvRedirects029 a redirect rewrites the method only as RFC 9110 section 15.4 allows")
        fun redirectMethodRewritingFollowsRfc9110() {
            val cases =
                listOf(
                    Triple(301, "POST", "GET"),
                    Triple(302, "POST", "GET"),
                    Triple(303, "POST", "GET"),
                    Triple(301, "PUT", "PUT"),
                    Triple(302, "PATCH", "PATCH"),
                    Triple(302, "DELETE", "DELETE"),
                    Triple(303, "PUT", "GET"),
                    Triple(303, "DELETE", "GET"),
                    Triple(303, "HEAD", "HEAD"),
                    Triple(307, "POST", "POST"),
                    Triple(308, "PUT", "PUT"),
                )
            for ((status, method, expected) in cases) {
                var hopCount = 0
                var secondHopMethod: String? = null
                val engine =
                    MockEngine { req ->
                        hopCount++
                        if (hopCount == 1) {
                            respond(
                                content = "",
                                status = HttpStatusCode.fromValue(status),
                                headers = headersOf("Location", "https://other.example.com/dest"),
                            )
                        } else {
                            secondHopMethod = req.method.value
                            respond("ok", HttpStatusCode.OK, headersOf("Content-Type", "text/plain"))
                        }
                    }
                val transport = TransportOptions.builder().followRedirects(true).build()
                val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false }, transport)
                runBlocking {
                    apiClient.sendRequest(method, "https://secure.example.com/x", emptyMap(), "body")
                }
                assertEquals(expected, secondHopMethod, "$status $method")
            }
        }

