    @Nested
    @DisplayName("redirect default-port normalization")
    inner class RedirectDefaultPortNormalization {
        /*
         * Regression: same-origin check on redirect previously compared raw
         * URI.port values, so a redirect from `https://host/x` (port -1) to
         * `https://host:443/y` (port 443) was treated as cross-origin and
         * the Authorization header was stripped. effectivePort(...) normalizes
         * the omitted port to the scheme's default so the two URIs compare
         * equal and credentials survive the hop.
         */
        @Test
        @DisplayName("bhvRedirects030 an explicit default port is the same origin as the implicit one")
        fun redirectToExplicitDefaultPortPreservesAuthorizationImplicit() {
            assertTrue(
                sameOrigin(java.net.URI("https://host/x"), java.net.URI("https://host:443/y")),
                "explicit :443 must be the same origin as the implicit https port",
            )
            assertTrue(
                sameOrigin(java.net.URI("http://host/x"), java.net.URI("http://host:80/y")),
                "explicit :80 must be the same origin as the implicit http port",
            )
            assertEquals(
                443,
                effectivePort(java.net.URI("https://host/x")),
                "implicit https port must normalize to 443",
            )
            assertEquals(
                443,
                effectivePort(java.net.URI("https://host:443/y")),
                "explicit :443 must round-trip as 443",
            )
            assertEquals(
                80,
                effectivePort(java.net.URI("http://host/x")),
                "implicit http port must normalize to 80",
            )
            assertEquals(
                80,
                effectivePort(java.net.URI("http://host:80/y")),
                "explicit :80 must round-trip as 80",
            )
            assertEquals(
                8443,
                effectivePort(java.net.URI("https://host:8443/y")),
                "non-default ports must round-trip unchanged",
            )
        }

        @Test
        @DisplayName("bhvRedirects037 a redirect to the explicit default port of the same origin keeps the Authorization header")
        fun redirectToExplicitDefaultPortPreservesAuthorization() {
            assertTrue(
                sameOrigin(java.net.URI("https://host/x"), java.net.URI("https://host:443/y")),
                "explicit :443 must be the same origin as the implicit https port",
            )
            assertTrue(
                sameOrigin(java.net.URI("http://host/x"), java.net.URI("http://host:80/y")),
                "explicit :80 must be the same origin as the implicit http port",
            )
            assertEquals(
                443,
                effectivePort(java.net.URI("https://host/x")),
                "implicit https port must normalize to 443",
            )
            assertEquals(
                443,
                effectivePort(java.net.URI("https://host:443/y")),
                "explicit :443 must round-trip as 443",
            )
            assertEquals(
                80,
                effectivePort(java.net.URI("http://host/x")),
                "implicit http port must normalize to 80",
            )
            assertEquals(
                80,
                effectivePort(java.net.URI("http://host:80/y")),
                "explicit :80 must round-trip as 80",
            )
            assertEquals(
                8443,
                effectivePort(java.net.URI("https://host:8443/y")),
                "non-default ports must round-trip unchanged",
            )
        }

        @Test
        @DisplayName("bhvRedirects034 origin comparison separates a different scheme, host or port")
        fun originComparisonSeparatesSchemeHostAndPort() {
            val base = java.net.URI("https://host:8443/x")
            assertFalse(sameOrigin(base, java.net.URI("http://host:8443/y")), "a different scheme")
            assertFalse(sameOrigin(base, java.net.URI("https://other:8443/y")), "a different host")
            assertFalse(sameOrigin(base, java.net.URI("https://host:9443/y")), "a different port")
        }

        /*
         * Security regression: a 30x from `https://host/x` to `http://host/x`
         * is a TLS downgrade; the Authorization (and other sensitive) headers
         * MUST be stripped on the follow-up. Previously sameOrigin() only
         * compared host + port and so happily forwarded the Authorization
         * over plain HTTP.
         */
        @Test
        @DisplayName("bhvRedirects053 Authorization is removed when the scheme changes between https and http on the same host")
        fun bhvRedirects053StripsAuthorizationOnSchemeChange() {
            assertFalse(
                sameOrigin(
                    java.net.URI("https://host:8443/x"),
                    java.net.URI("http://host:8443/y"),
                ),
                "https→http redirect MUST be cross-origin (TLS downgrade)",
            )
            assertFalse(
                sameOrigin(
                    java.net.URI("http://host:8080/x"),
                    java.net.URI("https://host:8080/y"),
                ),
                "http→https redirect MUST be cross-origin (scheme changes)",
            )
            assertTrue(
                sameOrigin(
                    java.net.URI("https://host:8443/x"),
                    java.net.URI("https://host:8443/y"),
                ),
                "same-scheme same-host same-port must be same-origin",
            )
            assertTrue(
                sameOrigin(
                    java.net.URI("https://host/x"),
                    java.net.URI("https://host:443/y"),
                ),
                "implicit default port must compare equal to explicit",
            )
        }
    }

    @Nested
    @DisplayName("null-body Content-Length")
    inner class NullBodyContentLength {
        /*
         * Regression: POST/PUT/PATCH with body == null must emit an explicit
         * Content-Length: 0. Some servers / WAFs reject body-bearing verbs
         * with no Content-Length (411 Length Required). Kotlin attaches
         * an empty ByteArray(0) on the body-bearing verbs so Ktor's CIO
         * engine emits the header.
         */
        @Test
        @DisplayName("bhvTransport019 post_with_null_body_sends_content_length_zero")
        fun postWithNullBodySendsContentLengthZero() {
            val chasmUrl = ChasmContainer.getBaseUrl()
            val client = DefaultApiClient()
            val response =
                runBlocking {
                    client.sendRequest("POST", "$chasmUrl/test/echo", emptyMap(), null)
                }
            assertEquals(200, response.statusCode)
            val json: JsonNode = ObjectMapper().readTree(response.body)
            assertEquals(
                0,
                json.get("contentLength").asInt(),
                "POST with null body must emit Content-Length: 0",
            )
        }
    }

    @Nested
    @DisplayName("client lifecycle (Gap T6)")
    inner class ClientLifecycle {
        @Test
        @DisplayName("bhvLifecycle018 close releases underlying client")
        fun closeReleasesUnderlyingClient() {
            val client = DefaultApiClient()
            client.close()
            // Calling close again is idempotent.
            client.close()
            val thrown =
                assertThrowsExactly(IllegalStateException::class.java) {
                    runBlocking {
                        client.sendRequest("GET", "https://example.com", emptyMap(), null)
                    }
                }
            assertTrue(
                thrown.message?.contains("closed") == true,
                "expected a closed-client message, got ${thrown.message}",
            )
        }
    }
}
